insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (135, 2, 2, 'SPIRIT-TCM 2018 针刺扩展清单', 'SPIRIT-TCM 2018 Acupuncture Extension Checklist', '背景和依据：针刺干预依据', 'Background and rationale: Acupuncture rationale', '6a.2', '6a.2', '描述所采用针刺干预的理论依据，并提供参考文献。对于针刺，应说明治疗方案依据是否来源于历史背景、已有研究、专家共识或其他方法。', 'Describe the rationale of the utilized acupuncture intervention with references. For acupuncture, the description should include the rationale for treatment protocol, whether it is from historical context, available studies, and/or consensus methods. Corresponding references should also be provided.', '', '', '', '', 56, '0', '0', 'migration', current_timestamp);
