insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (154, 2, 2, 'SPIRIT-TCM 2018 针刺扩展清单', 'SPIRIT-TCM 2018 Acupuncture Extension Checklist', '其他干预措施', 'Other interventions', '11d.2', '11d.2', '建议描述试验组和/或对照组将接受的其他干预，例如救援干预、常规治疗或合并治疗，并提供足够细节以便重复。', 'Descriptions of other interventions that will be administrated to experimental and/or control groups are recommended, e.g., rescue interventions, with enough details to allow replication.', '', '', '', '', 75, '0', '0', 'migration', current_timestamp);
