insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (156, 2, 2, 'SPIRIT-TCM 2018 针刺扩展清单', 'SPIRIT-TCM 2018 Acupuncture Extension Checklist', '结局指标：中医相关结局评价', 'Outcomes: TCM-related outcome assessment', '12b', '12b', '详细说明中医相关结局评价，包括：1）测量方法和标准，例如症状体征频率、严重程度评分、经过验证的证候问卷、评价时间点及其理由；2）评价者资质，例如相关评价经验、临床实践年限；3）提高评价质量的方法，例如重复观察、评价者培训；4）相关参考文献。', 'Provide the details of the TCM-related outcomes assessment, including: 1) the measuring methods and standard, e.g., frequency, severity rating scale of symptoms and signs, verified pattern questionnaire, time points for assessment and corresponding rationale; 2) assessor qualification, e.g., relevant assessment experience, years in clinical practice; 3) methods used to enhance the quality of assessment, e.g., multiple repeated observation, training of assessors; and 4) related references.', '', '', '', '', 77, '0', '0', 'migration', current_timestamp);
