insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (158, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '标题：标题', 'Title', '1', '1', '明确报告研究是系统评价、Meta分析，还是两者兼有；如果研究了具体的针刺类型，则应在题目中说明，如手法针刺或电针。', 'Identify the report as a systematic review, meta-analysis, or both; if applicable, state the specific type of acupuncture treatment, such as manual acupuncture or electroacupuncture.', '', '', '', '', 0, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (159, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '摘要：结构式摘要', 'Structured summary', '2', '2', '提供结构式摘要，包括研究背景、目的、资料来源、纳入排除标准、研究对象/干预措施、研究评价和综合方法、结果、局限、结论和主要发现、系统评价注册号。', 'Provide a structured summary including, as applicable: background; objectives; data sources; study eligibility criteria, participants, and interventions; study appraisal and synthesis methods; results limitations; conclusions and implications of key findings; systematic review registration number.', '', '', '', '', 1, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (160, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '前言：理论基础', 'Rationale', '3', '3', '在背景中描述已知的针刺干预对目标疾病或症状的作用原理；若适用，需具体到拟研究的特定针刺类型，并描述不同针刺类型之间的效果是否有差异。', 'Describe the rationale for what is already known about acupuncture for the target condition in the background; if applicable, state what is already known about the specific types of acupuncture to be studied, and describe whether there is any difference of the effects among different types of acupuncture.', '', '', '', '', 2, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (161, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '前言：研究目的', 'Objectives', '4', '4', '基于研究对象、干预措施、对照措施、结局指标和研究类型，即 PICOS，提出清晰明确的研究问题。', 'Provide an explicit statement of questions being addressed with reference to participants, interventions, comparisons, outcomes, and study design, PICOS.', '', '', '', '', 3, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (162, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '方法：方案和注册', 'Protocol and registration', '5', '5', '如果已有研究方案，则说明方案内容并给出可获得途径，如网址；并提供现有注册信息，包括注册号。', 'Indicate if a review protocol exists, if and where it can be accessed, e.g. web address, and, if available, provide registration information including registration number.', '', '', '', '', 4, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (163, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '方法：纳入排除标准', 'Eligibility criteria', '6', '6', '说明作为纳入排除标准的研究特征，如 PICOS 和随访时间，以及报告特征，如发表年份、语言和发表状态，并给出理由。', 'Specify study characteristics, e.g. PICOS and length of follow-up, and report characteristics, e.g. years considered, language and publication status, used as criteria for eligibility, giving rationale.', '', '', '', '', 5, '0', '0', 'migration', current_timestamp);
