insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (168, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '方法：检索信息来源', 'Information sources', '7', '7', '描述检索的所有信息来源，例如数据库、检索时间范围、是否联系研究作者确定是否存在更多相关研究，并报告最后检索日期；如适用，报告针刺或传统医学相关数据库或补充检索方法。', 'Describe all sources of information, e.g. databases with dates of coverage and contact with study authors to identify additional studies, in the search, and report the date of the last search. If applicable, report the databases or complementary search methods for acupuncture or traditional medicine.', '', '', '', '', 10, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (169, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '方法：文献检索', 'Search', '8', '8', '提供至少一个常用数据库，如 MEDLINE，的完整检索策略，包括所有限定条件，以保证检索方法可重复；如同时检索综合数据库和传统医学数据库，则至少提供一个综合数据库和一个传统医学数据库的完整检索策略。', 'Present full electronic search strategy for at least one commonly used database, e.g. MEDLINE, including any limits used, such that it could be repeated. If applicable, include the full search strategy for at least a Western and a traditional medicine database for each systematic review where both were used.', '', '', '', '', 11, '0', '0', 'migration', current_timestamp);
