insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (171, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '方法：数据提取过程', 'Data collection process', '10', '10', '描述资料提取方法，如设计提取表格、独立提取、重复提取，以及向纳入研究作者获取或确认资料和数据的过程。', 'Describe method of data extraction from reports, e.g. piloted forms, independently, in duplicate, and any processes for obtaining and confirming data from investigators.', '', '', '', '', 13, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (172, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '方法：数据提取条目', 'Data items', '11', '11', '列出并定义要搜集的所有数据类型，如 PICOS 和资金来源；如适用，描述参考用于制定数据提取表的工具，如 STRICTA 和 TIDieR；对于干预措施信息的提取，针刺干预组和对照组，如假针刺，的详细程度应一致。', 'List and define all variables for which data were sought, e.g. PICOS and funding sources, and any assumptions and simplifications made; describe data items about details of acupuncture interventions and controls, e.g. sham acupuncture, referring to TIDieR when applicable.', '', '', '', '', 14, '0', '0', 'migration', current_timestamp);
