insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (179, 3, 1, 'PRISMA-A 条目清单', 'PRISMA-A Checklist', '结果：研究特性', 'Study characteristics', '18', '18', '对于每项研究，报告提取的研究特征，如样本量、PICOS、随访时间，并提供纳入研究的引文；参考 TIDieR 模板和 STRICTA 总结针刺干预特征，将每项研究的针刺干预细节总结在表格中。', 'For each study, present characteristics that were extracted, e.g. study size, PICOS and follow-up period, and provide citations of the included studies. Summarize details of the acupuncture intervention for each study in a table referring to TIDieR.', '', '', '', '', 21, '0', '0', 'migration', current_timestamp);
