insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (248, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '推荐意见：推荐理由/解释', 'Recommendations: Rationale/explanation for recommendations', '15a', '15a', '描述在形成每条推荐意见时，是否陈述了目标人群的基础价值观和偏好。如是，应描述用于获取或识别这些价值观和偏好的方法。', 'Describe whether the underlined values and preferences of the target population(s) were stated in the formulation of each recommendation. If yes, describe the approaches and methods used to elicit or identify these values and preferences.', '', '', '', '', 28, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (249, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '推荐意见：推荐理由/解释', 'Recommendations: Rationale/explanation for recommendations', '15b', '15b', '描述在形成推荐意见时，是否考虑了成本和资源影响。如是，应描述所用具体方法，例如成本-效果分析，并总结结果。如未考虑资源问题，应提供解释。', 'Describe whether cost and resource implications were considered in the formulation of the recommendations. If yes, describe the specific approaches and methods used, such as cost-effectiveness analysis, and summarize the results. If resource issues were not considered, provide an explanation.', '', '', '', '', 29, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (250, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '推荐意见：推荐理由/解释', 'Recommendations: Rationale/explanation for recommendations', '15c', '15c', '描述形成推荐意见时考虑的其他因素，例如公平性、可行性和可接受性。', 'Describe other factors taken into consideration when formulating the recommendations, such as equity, feasibility and acceptability.', '', '', '', '', 30, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (251, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '推荐意见：推荐理由/解释', 'Recommendations: Rationale/explanation for recommendations', '15d', '15d', '描述经典古籍、传统医学医师经验和技术规范是否以及如何影响推荐意见。', 'Describe whether, and how, classical books, traditional medicine physicians’ experience and technical specifications influenced the recommendations.', '', '', '', '', 31, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (252, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '推荐意见：从证据到决策过程', 'Recommendations: Evidence to decision processes', '16', '16', '描述指南制定小组作出决策所用的过程和方法，特别是推荐意见的形成过程，例如如何定义并达成共识，以及是否使用投票。', 'Describe the processes and approaches used by the guideline development group to make decisions, particularly the formulation of recommendations, such as how consensus was defined and achieved and whether voting was used.', '', '', '', '', 32, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (253, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '评审和质量保证：外部评审', 'Review and Quality Assurance: External review', '17', '17', '说明指南草案是否经过独立评审；如是，应说明评审如何实施，以及如何考虑和处理评审意见。如适用，应列出外部评审专家组，例如资深针灸专家、临床一线针灸师和方法学专家。', 'Indicate whether the draft guideline underwent independent review and, if so, how the review was executed and the comments considered and addressed. The external review panel, for example senior acupuncture specialists, clinical first-line acupuncturists and methodologists, should be listed if applicable.', '', '', '', '', 33, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (254, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '评审和质量保证：质量保证', 'Review and Quality Assurance: Quality assurance', '18', '18', '说明指南是否经过质量保证过程。如是，应描述该过程。如适用，应向相关卫生机构、针灸专业学会或相关组织提交意见函以供批准。', 'Indicate whether the guideline was subject to a quality assurance process. If yes, describe the process. Submit a letter of opinion to the relevant health institution, the acupuncture professional society or the relevant organization, if applicable, for approval.', '', '', '', '', 34, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (255, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '资助及利益声明和管理：资助来源及资助方作用', 'Funding and Declaration and Management of Interests: Funding source(s) and role(s) of the funder', '19a', '19a', '描述指南制定所有阶段的具体资助来源。', 'Describe the specific sources of funding for all stages of guideline development.', '', '', '', '', 35, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (256, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '资助及利益声明和管理：资助来源及资助方作用', 'Funding and Declaration and Management of Interests: Funding source(s) and role(s) of the funder', '19b', '19b', '描述资助方在指南制定不同阶段以及推荐意见传播和实施中的作用。', 'Describe the role of funder(s) in the different stages of guideline development and in the dissemination and implementation of the recommendations.', '', '', '', '', 36, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (257, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '资助及利益声明和管理：利益冲突声明和管理', 'Funding and Declaration and Management of Interests: Declaration and management of conflict interest', '20a', '20a', '描述与指南制定相关的利益冲突，包括经济性和非经济性利益冲突。', 'Describe the conflicts of interest, financial and non-financial, that were relevant to guideline development.', '', '', '', '', 37, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (258, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '资助及利益声明和管理：利益冲突声明和管理', 'Funding and Declaration and Management of Interests: Declaration and management of conflict interest', '20b', '20b', '描述利益冲突如何被评价和管理，以及指南使用者如何获取利益声明。', 'Describe how conflicts of interest were evaluated and managed and how users of the guideline can access the declarations.', '', '', '', '', 38, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (259, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '其他信息：获取途径', 'Other Information: Access', '21', '21', '描述指南、附录和其他相关文件可从何处获取。', 'Describe where the guideline, its appendices, and other related documents can be accessed.', '', '', '', '', 39, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (260, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '其他信息：未来研究建议', 'Other Information: Suggestions for further research', '22', '22', '描述证据空白，和/或提出未来研究建议。', 'Describe the gaps in the evidence and/or provide suggestions for future research.', '', '', '', '', 40, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (261, 5, 1, '“RIGHT for Acupuncture” 清单', '“RIGHT for Acupuncture” Checklist', '其他信息：指南局限性', 'Other Information: Limitations of the guideline', '23', '23', '描述指南制定过程中的任何局限性，例如制定小组并非多学科组成，或未获取患者价值观和偏好；并说明这些局限性可能如何影响推荐意见的有效性。', 'Describe any limitations in the guideline development process, such as the development groups were not multidisciplinary or patients’ values and preferences were not sought, and indicate how these limitations might have affected the validity of the recommendations.', '', '', '', '', 41, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (262, 6, 1, '一、ARRIVE 关键 10 条', 'The ARRIVE Essential 10', '研究设计', 'Study design', '1', '1', '对于每个实验，给出简要的研究设计细节，包括：a. 比较的组别，包括对照组；如果没有对照组，应阐明理由。b. 实验单元，如单只动物、一窝动物或一笼动物。', 'For each experiment, provide brief details of study design including: a. The groups being compared, including control groups. If no control group has been used, the rationale should be stated. b. The experimental unit, e.g. a single animal, litter, or cage of animals.', '', '', '', '', 0, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (263, 6, 1, '一、ARRIVE 关键 10 条', 'The ARRIVE Essential 10', '样本量', 'Sample size', '2', '2', 'a. 详细说明分配给每个实验组的确切实验单元，以及每次实验的动物总数、整个实验使用的动物总数。b. 解释样本量如何决定；如进行了样本量计算，应提供预先计算细节。', 'a. Specify the exact number of experimental units allocated to each group, and the total number in each experiment. Also indicate the total number of animals used. b. Explain how the sample size was decided. Provide details of any a priori sample size calculation, if done.', '', '', '', '', 1, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (264, 6, 1, '一、ARRIVE 关键 10 条', 'The ARRIVE Essential 10', '纳入和排除标准', 'Inclusion and exclusion criteria', '3', '3', 'a. 描述实验期间用于纳入和排除动物、实验单元或数据点的标准，并说明是否预先设立。b. 报告每组分析中被排除的动物、实验单元或数据点及原因；如无排除，也应说明。c. 对于每次分析，报告每组实验单元的准确数量。', 'a. Describe any criteria used for including and excluding animals or experimental units during the experiment, and data points during the analysis. Specify if these criteria were established a priori. If no criteria were set, state this explicitly. b. For each experimental group, report any animals, experimental units or data points not included in the analysis and explain why. If there were no exclusions, state so. c. For each analysis, report the exact value of n in each experimental group.', '', '', '', '', 2, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (265, 6, 1, '一、ARRIVE 关键 10 条', 'The ARRIVE Essential 10', '随机化', 'Randomization', '4', '4', 'a. 说明是否采用随机化方法将实验单元分配至对照组和处理组；如采用随机化，应提供随机序列生成方法。b. 描述用于减少潜在混杂因素的策略，如处理和测量顺序、动物或笼子位置；如未控制混杂因素，应明确说明。', 'a. State whether randomisation was used to allocate experimental units to control and treatment groups. If done, provide the method used to generate the randomisation sequence. b. Describe the strategy used to minimise potential confounders such as the order of treatments and measurements, or animal/cage location. If confounders were not controlled, state this explicitly.', '', '', '', '', 3, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (266, 6, 1, '一、ARRIVE 关键 10 条', 'The ARRIVE Essential 10', '盲法', 'Blinding', '5', '5', '描述实验不同阶段谁知晓分组情况，包括分配、实验实施、结局评价和数据分析。', 'Describe who was aware of the group allocation at the different stages of the experiment, including allocation, conduct of the experiment, outcome assessment, and data analysis.', '', '', '', '', 4, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (267, 6, 1, '一、ARRIVE 关键 10 条', 'The ARRIVE Essential 10', '结局评价', 'Outcome measures', '6', '6', 'a. 清晰定义所有结局评价指标，如细胞死亡、分子标记或行为改变。b. 对于假说检验性研究，应明确主要结局指标，例如用于样本量计算的结局指标。', 'a. Clearly define all outcome measures assessed, e.g. cell death, molecular markers, or behavioural changes. b. For hypothesis-testing studies, specify the primary outcome measure, i.e. the outcome measure used to determine the sample size.', '', '', '', '', 5, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (268, 6, 1, '一、ARRIVE 关键 10 条', 'The ARRIVE Essential 10', '统计方法', 'Statistical methods', '7', '7', 'a. 提供每次分析所用统计方法的细节，包括统计软件。b. 描述如何评估数据是否满足统计假设，以及当统计假设不满足时所做的方法变更。', 'a. Provide details of the statistical methods used for each analysis, including software used. b. Describe any methods used to assess whether the data met the assumptions of the statistical approach, and what was done if the assumptions were not met.', '', '', '', '', 6, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (269, 6, 1, '一、ARRIVE 关键 10 条', 'The ARRIVE Essential 10', '实验动物', 'Experimental animals', '8', '8', 'a. 提供动物种类的详细资料，包括物种、品系、亚系、雌雄、年龄或发育阶段，以及相关时的体重。b. 提供动物来源、健康/免疫状态、基因修饰状态、基因型和既往实验使用情况等。', 'a. Provide species-appropriate details of the animals used, including species, strain and substrain, sex, age or developmental stage, and, if relevant, weight. b. Provide further relevant information on the provenance of animals, health/immune status, genetic modification status, genotype, and any previous procedures.', '', '', '', '', 7, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (270, 6, 1, '一、ARRIVE 关键 10 条', 'The ARRIVE Essential 10', '实验步骤', 'Experimental procedures', '9', '9', '对每个实验组，包括对照组，描述足以让其他研究者重复实验的细节，包括：a. 内容、方法和材料。b. 时间和频次。c. 地点，包括适应期细节。d. 进行这些程序的理由。', 'For each experimental group, including controls, describe the procedures in enough detail to allow others to replicate them, including: a. What was done, how it was done and what was used. b. When and how often. c. Where, including details of any acclimatisation periods. d. Why, providing rationale for procedures.', '', '', '', '', 8, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (271, 6, 1, '一、ARRIVE 关键 10 条', 'The ARRIVE Essential 10', '结果', 'Results', '10', '10', '对每次实验，包括独立重复实验，报告：a. 每组的总结性或描述性统计结果，并在适用时报告变异度，如均值和标准差、中位数和范围。b. 适用时报告效应量及其可信区间。', 'For each experiment conducted, including independent replications, report: a. Summary/descriptive statistics for each experimental group, with a measure of variability where applicable, e.g. mean and SD, or median and range. b. If applicable, the effect size with a confidence interval.', '', '', '', '', 9, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (272, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '摘要', 'Abstract', '11', '11', '提供准确摘要，包括研究目标、动物物种、品系和雌雄、关键方法、主要结果和研究结论。', 'Provide an accurate summary of the research objectives, animal species, strain and sex, key methods, principal findings, and study conclusions.', '', '', '', '', 10, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (273, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '研究背景', 'Background', '12', '12', 'a. 包括足够科学背景，有助于理解研究理由和背景，并解释实验方案。b. 解释实验中使用的动物种类和模型如何达到研究目标；适用时，说明与人类生物学的相关性。', 'a. Include sufficient scientific background to understand the rationale and context for the study, and explain the experimental approach. b. Explain how the animal species and model used address the scientific objectives and, where appropriate, the relevance to human biology.', '', '', '', '', 11, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (274, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '研究目标', 'Objectives', '13', '13', '清楚描述研究问题、研究目标；适用时，说明研究的具体假说。', 'Clearly describe the research question, research objectives and, where appropriate, specific hypotheses being tested.', '', '', '', '', 12, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (275, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '伦理声明', 'Ethical statement', '14', '14', '提供批准本次动物实验的伦理审查委员会或相应机构名称，以及相关许可证或方案编号。如未申请或未获得伦理批准，应说明原因。', 'Provide the name of the ethical review committee or equivalent that has approved the use of animals in this study, and any relevant licence or protocol numbers, if applicable. If ethical approval was not sought or granted, provide a justification.', '', '', '', '', 13, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (276, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '饲养场所和饲养', 'Housing and husbandry', '15', '15', '提供饲养场所和饲养条件的细节，包括环境改善措施。', 'Provide details of housing and husbandry conditions, including any environmental enrichment.', '', '', '', '', 14, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (277, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '动物饲养、监测', 'Animal care and monitoring', '16', '16', 'a. 描述实验方案中为减轻动物疼痛、折磨和苦痛所采取的干预措施或步骤。b. 报告任何预期或非预期不良事件。c. 描述人道终点、监测指标和监测频率；如未采用人道终点，应说明。', 'a. Describe any interventions or steps taken in the experimental protocols to reduce pain, suffering and distress. b. Report any expected or unexpected adverse events. c. Describe the humane endpoints established for the study, the signs that were monitored and the frequency of monitoring. If the study did not have humane endpoints, state this.', '', '', '', '', 15, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (278, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '诠释/科学内涵', 'Interpretation / scientific implications', '17', '17', 'a. 结合研究目标和假说、当前理论及相关文献解释结果。b. 评价研究局限性，包括潜在偏倚来源、动物模型局限性和结果不精确性。', 'a. Interpret the results, taking into account the study objectives and hypotheses, current theory and other relevant studies in the literature. b. Comment on the study limitations including potential sources of bias, limitations of the animal model, and imprecision associated with the results.', '', '', '', '', 16, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (279, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '可推广性/转化', 'Generalisability / translation', '18', '18', '讨论研究结果是否以及如何可能适用于其他物种或实验条件；适用时，说明与人类生物学的关联。', 'Comment on whether, and how, the findings of this study are likely to generalise to other species or experimental conditions, including any relevance to human biology, where appropriate.', '', '', '', '', 17, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (280, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '实验方案注册', 'Protocol registration', '19', '19', '声明研究前是否准备了实验方案，包括研究问题、关键设计特点和分析计划；说明该实验方案是否注册，以及在哪里注册。', 'Provide a statement indicating whether a protocol, including the research question, key design features, and analysis plan, was prepared before the study, and if and where this protocol was registered.', '', '', '', '', 18, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (281, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '数据获取', 'Data access', '20', '20', '声明研究数据是否可以获取，以及可以从何处或通过何种方式获得。', 'Provide a statement describing if and where study data are available.', '', '', '', '', 19, '0', '0', 'migration', current_timestamp);
insert into action_guideline_item (item_id, guideline_id, part_no, part_zh, part_en, domain_zh, domain_en, item_no_zh, item_no_en, content_zh, content_en, ext_label_zh, ext_label_en, extension_zh, extension_en, sort_num, status, del_flag, create_by, create_time) values (282, 6, 2, 'ARRIVE 建议条目集', 'The Recommended Set', '利益冲突声明', 'Declaration of interests', '21', '21', 'a. 声明任何潜在利益冲突，包括经济和非经济利益冲突；如无利益冲突，也应声明。b. 列出所有资助来源，包括课题编号，并说明资助方在研究设计、分析和报告中的作用。', 'a. Declare any potential conflicts of interest, including financial and non-financial. If none exist, this should be stated. b. List all funding sources, including grant identifier, and the role of the funder(s) in the design, analysis and reporting of the study.', '', '', '', '', 20, '0', '0', 'migration', current_timestamp);
